class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        rc = cc = 0
        for row in grid:
            for j in range(n // 2):
                rc += row[j] != row[n - 1 - j]
        for j in range(n):
            for i in range(m // 2):
                cc += grid[i][j] != grid[m - 1 - i][j]
        return min(rc, cc)

