class Solution {
public:
    int minFlips(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int rc = 0, cc = 0;
        for (auto& row : grid)
            for (int j = 0; j < n / 2; ++j)
                rc += row[j] != row[n - 1 - j];
        for (int j = 0; j < n; ++j)
            for (int i = 0; i < m / 2; ++i)
                cc += grid[i][j] != grid[m - 1 - i][j];
        return min(rc, cc);
    }
};

