class Solution {
    public int minFlips(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int rc = 0, cc = 0;
        for (int[] row : grid)
            for (int j = 0; j < n / 2; ++j)
                rc += row[j] != row[n - 1 - j] ? 1 : 0;
        for (int j = 0; j < n; ++j)
            for (int i = 0; i < m / 2; ++i)
                cc += grid[i][j] != grid[m - 1 - i][j] ? 1 : 0;
        return Math.min(rc, cc);
    }
}

