var minFlips = function(grid) {
    const m = grid.length, n = grid[0].length;
    let rc = 0, cc = 0;
    for (const row of grid)
        for (let j = 0; j < n >> 1; ++j)
            rc += row[j] !== row[n - 1 - j] ? 1 : 0;
    for (let j = 0; j < n; ++j)
        for (let i = 0; i < m >> 1; ++i)
            cc += grid[i][j] !== grid[m - 1 - i][j] ? 1 : 0;
    return Math.min(rc, cc);
};
